151	fn supervisor_config(request: &SemanticRequest) -> Result<SupervisorConfig, String> {
152	    let tsc_path = locate::find_tsc(&request.project_root, request.tsc_path.as_deref())?;
153	    let mut config = SupervisorConfig::new(tsc_path, request.project_root.clone(), request.expected_versions);
154	    config.handshake_timeout = request.request_timeout;
155	    config.extra_env.clone_from(&request.extra_env);
