159	async fn run(request: SemanticRequest) -> SemanticOutcome {
160	    if !request.targets.iter().any(|target| target.exported) {
161	        return group_by_file(&request).0;
162	    }
163	    let config = match supervisor_config(&request) {
164	        Ok(config) => config,
165	        Err(reason) => return SemanticOutcome::unavailable(reason),
166	    };
167	    let supervisor = match Supervisor::spawn(config).await {
168	        Ok(supervisor) => supervisor,
169	        Err(error) => return SemanticOutcome::unavailable(error.to_string()),
170	    };
171	    let outcome = answer_with(&supervisor, &request).await;
172	    supervisor.shutdown().await.ok();
173	    outcome
174	}
