212	async fn session(
213	    rpc: &Arc<Rpc>,
214	    request: &SemanticRequest,
215	    files: &[String],
216	    by_file: &FxHashMap<&Utf8Path, Vec<&Target>>,
217	    order: &[&Utf8Path],
218	) -> Result<SemanticOutcome, CallError> {
219	    let started = std::time::Instant::now();
220	    let converter = Converter::new(rpc.clone(), request.reverse_queries);
221	    let limit = Arc::new(Semaphore::new(FILES_IN_FLIGHT));
222	    let interner = Arc::new(PropInterner::default());
223	
224	    let mut tasks = JoinSet::new();
225	    for file in order {
226	        let targets: Vec<Target> = by_file.get(file).into_iter().flatten().map(|target| (*target).clone()).collect();
227	        let (rpc, converter, limit, interner) = (rpc.clone(), converter.clone(), limit.clone(), interner.clone());
228	        tasks.spawn(async move {
229	            let _permit = limit.acquire().await;
230	            answer_file(&rpc, &converter, &interner, targets).await
231	        });
232	    }
233	
234	    let mut outcome = SemanticOutcome::default();
235	    let mut generic = Vec::new();
236	    let mut failure = None;
237	    while let Some(joined) = tasks.join_next().await {
238	        match joined {
239	            Ok(Ok((mut answered, mut instantiations))) => {
240	                outcome.components.append(&mut answered.components);
241	                outcome.fallbacks.append(&mut answered.fallbacks);
242	                generic.append(&mut instantiations);
243	            }
244	            Ok(Err(error)) => {
245	                failure = Some(error);
246	                tasks.abort_all();
247	            }
248	            // A panic inside a worker must not silently leave its components structural.
249	            Err(joined) if joined.is_panic() => {
250	                failure = Some(CallError::Fatal("a worker panicked".to_string()));
251	                tasks.abort_all();
252	            }
253	            // A cancelled task is one this loop aborted after a failure.
254	            Err(_cancelled) => {}
255	        }
256	    }
257	    if let Some(error) = failure {
258	        return Err(error);
259	    }
260	    if !generic.is_empty() {
261	        let mut instantiated =
262	            instantiate::answer(rpc, files, &request.project_root, &interner, request.reverse_queries, generic).await?;
263	        outcome.components.append(&mut instantiated.components);
264	        outcome.fallbacks.append(&mut instantiated.fallbacks);
265	    }
266	
267	    if let (Some(path), Some(recording)) = (&request.record_to, rpc.recording())
268	        && let Ok(json) = serde_json::to_string_pretty(&recording)
269	        && let Err(error) = std::fs::write(path, json)
270	    {
271	        tracing::warn!("could not write the recording to {path}: {error}");
272	    }
273	    tracing::debug!(
274	        requests = ?rpc.calls(),
275	        files = files.len(),
276	        type_memo = ?converter.memo_stats(),
277	        total_ms = started.elapsed().as_millis() as u64,
278	        "semantic backend finished"
279	    );
280	    outcome.components.sort_by(|a, b| (&a.file_path, &a.display_name).cmp(&(&b.file_path, &b.display_name)));
281	    outcome.fallbacks.sort_by(|a, b| (&a.file_path, &a.display_name).cmp(&(&b.file_path, &b.display_name)));
282	    Ok(outcome)
283	}
284	
285	fn fallback_of(target: &Target, reason: &str) -> SemanticFallback {
286	    SemanticFallback {
287	        file_path: target.file_path.clone(),
288	        display_name: target.display_name.clone(),
289	        reason: reason.to_string(),
290	    }
291	}
292	
293	/// A fatal error aborts the run; a call the checker rejected only sends that component to its structural result. The
294	/// generic components come back apart, to be answered from their instantiations once every file is done.
295	async fn answer_file(
296	    rpc: &Rpc,
297	    converter: &Converter,
298	    interner: &PropInterner,
299	    targets: Vec<Target>,
300	) -> Result<(SemanticOutcome, Vec<(Target, Instantiation)>), CallError> {
301	    let mut outcome = SemanticOutcome::default();
302	    let mut generic = Vec::new();
303	    let Some(first) = targets.first() else { return Ok((outcome, generic)) };
304	    let exports = match module_exports(rpc, first.file_path.as_str()).await {
305	        Ok(Some(exports)) => exports,
306	        Ok(None) | Err(CallError::Rejected(_)) => {
307	            outcome
308	                .fallbacks
309	                .extend(targets.iter().map(|target| fallback_of(target, "not part of the checker's program")));
310	            return Ok((outcome, generic));
311	        }
312	        Err(fatal) => return Err(fatal),
313	    };
314	
315	    for target in &targets {
316	        let requests = Arc::new(AtomicU64::new(0));
317	        let started = std::time::Instant::now();
318	        let answered =
319	            REQUESTS.scope(requests.clone(), component::props_of(rpc, converter, interner, &exports, target)).await;
320	        tracing::debug!(
321	            component = %target.display_name,
322	            requests = requests.load(Ordering::Relaxed),
323	            ms = started.elapsed().as_millis() as u64,
324	            "semantic component answered"
325	        );
326	        match answered {
327	            Ok(Answer::Props(props)) => outcome.components.push(SemanticComponent {
328	                file_path: target.file_path.clone(),
329	                display_name: target.display_name.clone(),
330	                props,
331	            }),
332	            Ok(Answer::Fallback(reason)) => outcome.fallbacks.push(fallback_of(target, &reason)),
333	            Ok(Answer::Instantiate(instantiation)) => generic.push((target.clone(), instantiation)),
334	            Err(CallError::Rejected(message)) => {
335	                outcome.fallbacks.push(fallback_of(target, &format!("the checker rejected a request: {message}")));
336	            }
337	            Err(fatal) => return Err(fatal),
338	        }
339	    }
340	    Ok((outcome, generic))
341	}
342	
343	async fn module_exports(rpc: &Rpc, file: &str) -> Result<Option<Vec<rpc::SymbolInfo>>, CallError> {
344	    let Some(module) = rpc.source_file_symbol(file).await? else { return Ok(None) };
345	    Ok(Some(rpc.exports_of_module(&module.reference).await?))
346	}
