1	//! What the experimental TypeScript checker backend hands back, and how it merges over the structural result.
2	//!
3	//! The backend (`caliper-docgen-semantic`) owns the process, the protocol and the checker walk; this module owns only
4	//! the result shape and the merge rules of `docs/type-checker-integration.md`, so `crates/core` stays free of I/O.
5	
6	use std::collections::BTreeMap;
7	use std::hash::{Hash, Hasher};
8	use std::sync::{Arc, Mutex};
9	
10	use camino::Utf8PathBuf;
11	use rustc_hash::{FxHashMap, FxHasher};
12	
13	mod order;
14	
15	use crate::types::diagnostic::{Diagnostic, DiagnosticCode, DiagnosticSeverity};
16	use crate::types::output::{
17	    ComponentEntry, ExtractionOutput, OpaqueDetail, OpaqueReason, ParsedProp, PropType, TRUNCATED_KIND,
18	};
19	
20	/// The type of a name the checker could not resolve (an import that does not resolve, a name declared nowhere), which
21	/// the checker answers with its error type: an `any` that is not a written `any`. It is `opaque` with the reason
22	/// `unresolvableImport`, so the prop carries `degradedBy`, and `written` is the name as the source writes it, which is
23	/// also what the reason names (the checker does not say which module specifier was behind it).
24	pub fn unresolved_type(written: impl Into<String>) -> PropType {
25	    let written = written.into();
26	    OpaqueDetail::new(written.clone(), OpaqueReason::UnresolvableImport { specifier: written })
27	}
28	
29	/// A type the checker holds that PropType has no shape for: a conditional or indexed access type it could not resolve
30	/// (its parameters are still open), `keyof T`. It is `opaque` with `reason`, so the prop carries `degradedBy`, and
31	/// `raw` is how the checker prints it.
32	pub fn degraded_type(raw: impl Into<String>, reason: OpaqueReason) -> PropType {
33	    OpaqueDetail::new(raw, reason)
34	}
35	
36	/// One prop as the checker reports it.
37	#[derive(Debug, Clone, PartialEq)]
38	pub struct SemanticProp {
39	    /// The prop's name as written in the props type.
40	    pub name: String,
41	    /// The type the checker computed for it, in the same shape the structural resolver produces.
42	    pub prop_type: PropType,
43	    /// Whether the checker found the prop non-optional.
44	    pub required: bool,
45	    /// The prop's JSDoc description, empty when it has none; the merge then keeps the structural description.
46	    pub description: String,
47	    /// Declared by `@types/react` (`children`, `aria-*`, handlers, `className`): not the component's own prop.
48	    pub react_declared: bool,
49	}
50	
51	impl SemanticProp {
52	    fn structural_hash(&self) -> u64 {
53	        let mut hasher = FxHasher::default();
54	        self.name.hash(&mut hasher);
55	        self.required.hash(&mut hasher);
56	        self.react_declared.hash(&mut hasher);
57	        self.description.hash(&mut hasher);
58	        self.prop_type.structural_hash(&mut hasher);
59	        hasher.finish()
60	    }
61	}
62	
63	/// Shares identical props between components, as the structural resolver does: a design system's components repeat
64	/// the same few hundred props, and Chakra's 600 components would otherwise hold 470,000 copies.
65	#[derive(Debug, Default)]
66	pub struct PropInterner {
67	    by_hash: Mutex<FxHashMap<u64, Vec<Arc<SemanticProp>>>>,
68	}
69	
70	impl PropInterner {
71	    /// The one shared copy of `prop`: an equal prop interned earlier, or `prop` itself the first time. If the internal
72	    /// lock is poisoned it returns `prop` unshared rather than failing.
73	    pub fn share(&self, prop: SemanticProp) -> Arc<SemanticProp> {
74	        let hash = prop.structural_hash();
75	        let Ok(mut by_hash) = self.by_hash.lock() else { return Arc::new(prop) };
76	        let bucket = by_hash.entry(hash).or_default();
77	        if let Some(existing) = bucket.iter().find(|existing| ***existing == prop) {
78	            return existing.clone();
79	        }
80	        let shared = Arc::new(prop);
81	        bucket.push(shared.clone());
82	        shared
83	    }
84	}
85	
86	/// One component the checker answered for, found by the file and name the structural pass reported.
87	#[derive(Debug, Clone, PartialEq)]
88	pub struct SemanticComponent {
89	    /// The file that declares the component, as the structural pass reported it.
90	    pub file_path: Utf8PathBuf,
91	    /// The component's name, as the structural pass reported it; with `file_path` it identifies the entry to merge into.
92	    pub display_name: String,
93	    /// Declared props in declaration order, with the `@types/react` ones the request asked for.
94	    pub props: Vec<Arc<SemanticProp>>,
95	}
96	
97	/// A component the backend left to the structural result, and why.
98	#[derive(Debug, Clone, PartialEq, Eq)]
99	pub struct SemanticFallback {
100	    /// The file that declares the component.
101	    pub file_path: Utf8PathBuf,
102	    /// The component's name, as the structural pass reported it.
103	    pub display_name: String,
104	    /// Why the checker did not answer, for example that the component is not exported by its module. The merge groups
105	    /// components by this text into one warning.
106	    pub reason: String,
107	}
108	
109	/// The backend's answer for a run. A backend that could not start returns no components and one diagnostic, never an
110	/// error: the structural result is always a complete answer on its own.
111	#[derive(Debug, Clone, Default, PartialEq)]
112	pub struct SemanticOutcome {
113	    /// The components the checker answered for; each replaces the props of the structural entry it names.
