311	/// Merge the checker's props over `output`, component by component.
312	///
313	/// Per `docs/type-checker-integration.md`: the checker decides which props exist, their types and whether they are
314	/// required; a description comes from the checker, else the structural pass; a default value stays structural (the
315	/// checker has no initializer for a destructured parameter); `parent` and `declarations` stay with the structural
316	/// prop of the same name. Inheritance layers and curated inherited props stay structural. Components the checker did
317	/// not answer for keep their structural result untouched.
318	///
319	/// Records provenance as `Info` diagnostics whose `affects` lists the output keys, so the canonical JSON gains no
320	/// field: one for the components the checker resolved, one per fallback reason.
321	pub fn merge_semantic(output: &mut ExtractionOutput, outcome: SemanticOutcome) {
322	    let SemanticOutcome { components, fallbacks, diagnostics } = outcome;
323	    let mut merged_keys = Vec::new();
324	    let (mut unread_keys, mut unread_props) = (Vec::new(), 0);
325	    let mut shared: FxHashMap<u64, Vec<Arc<ParsedProp>>> = FxHashMap::default();
326	    for semantic in components {
327	        let Some((key, entry)) = output
328	            .components
329	            .iter_mut()
330	            .find(|(_, entry)| entry.file_path == semantic.file_path && entry.display_name == semantic.display_name)
331	        else {
332	            continue;
333	        };
334	        let unread = apply_semantic_props(entry, &semantic, &mut shared);
335	        if unread > 0 {
336	            unread_props += unread;
337	            unread_keys.push(key.clone());
338	        }
339	        merged_keys.push(key.clone());
340	    }
341	    output.diagnostics.extend(diagnostics);
342	
343	    // A structural diagnostic about a prop the checker now answers for would be stale; the resolved component keeps
344	    // none of its degrade diagnostics.
345	    if !merged_keys.is_empty() {
346	        output.diagnostics.retain(|diagnostic| {
347	            let degrade = matches!(
348	                diagnostic.code,
349	                DiagnosticCode::OpaqueType | DiagnosticCode::MaxDepthExceeded | DiagnosticCode::CircularReference
350	            );
351	            !(degrade
352	                && !diagnostic.affects.is_empty()
353	                && diagnostic.affects.iter().all(|key| merged_keys.contains(key)))
354	        });
355	        merged_keys.sort();
356	        let mut provenance = Diagnostic::new(
357	            DiagnosticSeverity::Info,
358	            DiagnosticCode::SemanticBackend,
359	            format!("{} component(s) resolved by the TypeScript checker", merged_keys.len()),
360	        );
361	        provenance.affects = merged_keys;
362	        output.diagnostics.push(provenance);
363	    }
364	    if !unread_keys.is_empty() {
365	        unread_keys.sort();
366	        output.diagnostics.push(unread_diagnostic(unread_props, unread_keys));
367	    }
368	
369	    let mut by_reason: BTreeMap<String, Vec<String>> = BTreeMap::new();
370	    for fallback in fallbacks {
371	        let Some((key, _)) = output
372	            .components
373	            .iter()
374	            .find(|(_, entry)| entry.file_path == fallback.file_path && entry.display_name == fallback.display_name)
375	        else {
376	            continue;
377	        };
378	        by_reason.entry(fallback.reason).or_default().push(key.clone());
379	    }
380	    for (reason, mut keys) in by_reason {
381	        keys.sort();
382	        let mut diagnostic = Diagnostic::new(
383	            DiagnosticSeverity::Info,
384	            DiagnosticCode::SemanticBackend,
385	            format!("{} component(s) kept their structural result: {reason}", keys.len()),
386	        );
387	        diagnostic.affects = keys;
388	        output.diagnostics.push(diagnostic);
389	    }
390	}
