78	/// One whole-project request to the checker: the components to answer for, and how to reach `tsc`. Built with
79	/// [`SemanticRequest::new`] and answered by [`resolve`].
80	#[derive(Debug, Clone)]
81	pub struct SemanticRequest {
82	    /// Where `tsc` finds `node_modules`; its `--cwd`, and where the search for `typescript` starts.
