131	/// The exported targets by file, in first-seen order, and an outcome that already holds a fallback for each target
132	/// the checker cannot be asked about.
133	fn group_by_file(request: &SemanticRequest) -> (SemanticOutcome, FxHashMap<&Utf8Path, Vec<&Target>>, Vec<&Utf8Path>) {
134	    let mut outcome = SemanticOutcome::default();
135	    let mut by_file: FxHashMap<&Utf8Path, Vec<&Target>> = FxHashMap::default();
136	    let mut order: Vec<&Utf8Path> = Vec::new();
137	    for target in &request.targets {
138	        if !target.exported {
139	            outcome.fallbacks.push(fallback_of(target, "not exported by its module"));
140	            continue;
141	        }
142	        let group = by_file.entry(target.file_path.as_path()).or_default();
143	        if group.is_empty() {
144	            order.push(target.file_path.as_path());
145	        }
146	        group.push(target);
147	    }
148	    (outcome, by_file, order)
149	}
