181	/// Answers the request's targets with a checker that is already running: one program rooted at their files, released
182	/// once they are answered.
183	async fn answer_with(supervisor: &Supervisor, request: &SemanticRequest) -> SemanticOutcome {
184	    let files = root_files(request);
185	    if files.is_empty() {
186	        return group_by_file(request).0;
187	    }
188	    let started = std::time::Instant::now();
189	    let tsconfig = request.tsconfig.as_ref().map(|path| path.as_str());
190	    let opened =
191	        Rpc::open(supervisor.client(), request.request_timeout, tsconfig, &files, request.record_to.is_some()).await;
192	    let rpc = match opened {
193	        Ok(rpc) => Arc::new(rpc),
194	        Err(error) => return SemanticOutcome::unavailable(format!("the checker stopped answering: {error}")),
195	    };
196	    tracing::debug!(program_ms = started.elapsed().as_millis() as u64, "semantic program built");
197	    let answered = answer_on(&rpc, request, &files).await;
198	    rpc.release().await;
199	    answered.unwrap_or_else(|error| SemanticOutcome::unavailable(format!("the checker stopped answering: {error}")))
200	}
