202	/// Answers the request's targets on a snapshot whose program is rooted at `files` ([`root_files`]). The snapshot is
203	/// left as it is, for the caller to keep or release.
204	async fn answer_on(rpc: &Arc<Rpc>, request: &SemanticRequest, files: &[String]) -> Result<SemanticOutcome, CallError> {
205	    let (mut outcome, by_file, order) = group_by_file(request);
206	    let mut answered = session(rpc, request, files, &by_file, &order).await?;
207	    outcome.components.append(&mut answered.components);
208	    outcome.fallbacks.append(&mut answered.fallbacks);
209	    Ok(outcome)
210	}
