103	        match receiver.recv_timeout(self.wait) {
104	            Ok(outcome) => {
105	                let Read { answered, once } = read_outcome(&Asked::from(&answer), outcome);
106	                for diagnostic in once {
107	                    if !self.warned.swap(true, Ordering::Relaxed) {
108	                        answer.diagnostics.push(diagnostic);
109	                    }
110	                }
111	                answer.diagnostics.extend(answered.diagnostics.iter().cloned());
112	                let component = answered.component.clone();
