119	                self.keep_late_answer(receiver, &answer, cache_key, generation);
120	                let mut pending = Diagnostic::new(
121	                    DiagnosticSeverity::Info,
122	                    DiagnosticCode::SemanticBackend,
123	                    "the TypeScript checker has not answered yet; the structural props are used, and the checker's \
124	                     replace them on the next request",
125	                );
126	                pending.affects = vec![answer.key.clone()];
127	                answer.diagnostics.push(pending);
128	            }
129	            Err(RecvTimeoutError::Disconnected) => {
130	                let mut stopped = Diagnostic::new(
131	                    DiagnosticSeverity::Warning,
132	                    DiagnosticCode::SemanticBackend,
133	                    "the TypeScript checker stopped without answering; the structural props are used",
134	                );
135	                stopped.affects = vec![answer.key.clone()];
136	                answer.diagnostics.push(stopped);
137	            }
138	        }
