142	    fn generation(&self) -> u64 {
143	        self.answers.lock().unwrap_or_else(PoisonError::into_inner).generation
144	    }
145	
146	    fn cached(&self, key: &(String, u64)) -> Option<Answered> {
147	        self.answers.lock().unwrap_or_else(PoisonError::into_inner).answers.get(key).cloned()
148	    }
149	
150	    fn store(&self, key: (String, u64), generation: u64, answered: Answered) {
151	        store(&self.answers, key, generation, answered);
152	    }
153	
154	    /// Waits for an answer that missed its budget on a thread of its own, so the next request finds it.
155	    fn keep_late_answer(
156	        &self,
157	        receiver: Receiver<SemanticOutcome>,
158	        answer: &ComponentAnswer,
159	        cache_key: Option<(String, u64)>,
160	        generation: u64,
161	    ) {
162	        let Some(key) = cache_key else { return };
163	        let answers = self.answers.clone();
164	        let asked = Asked::from(answer);
165	        std::thread::Builder::new()
166	            .name("caliper-late-answer".to_string())
167	            .spawn(move || {
168	                if let Ok(outcome) = receiver.recv() {
169	                    store(&answers, key, generation, read_outcome(&asked, outcome).answered);
170	                }
171	            })
172	            .ok();
173	    }
174	
175	    fn apply(&self, answer: &mut ComponentAnswer, component: Option<&Arc<SemanticComponent>>, mode: HtmlAttributeMode) {
176	        let Some(component) = component else { return };
177	        let structural = answer.entry.props.clone();
178	        let used: Vec<&Arc<SemanticProp>> = component
179	            .props
180	            .iter()
181	            .filter(|prop| checker_prop_used(mode, &prop.name, prop.react_declared, &structural))
182	            .collect();
183	        // A degrade diagnostic names the component, not the prop, so it can only go once no structural prop is left
184	        // that it could be about: one the checker did not return keeps its structural type, opaque or not.
185	        let still_degraded = structural
186	            .iter()
187	            .any(|(name, prop)| prop.prop_type.holds_opaque() && !used.iter().any(|answered| answered.name == *name));
188	        let MergedProps { kept, unread } =
189	            merge_semantic_props(&mut answer.entry, used.into_iter(), &mut FxHashMap::default());
190	        if !still_degraded {
191	            // A structural diagnostic about a prop the checker now answers for would be stale.
192	            answer.diagnostics.retain(|diagnostic| {
193	                !matches!(
194	                    diagnostic.code,
195	                    DiagnosticCode::OpaqueType | DiagnosticCode::MaxDepthExceeded | DiagnosticCode::CircularReference
196	                )
197	            });
198	        }
199	        let mut provenance = Diagnostic::new(
200	            DiagnosticSeverity::Info,
201	            DiagnosticCode::SemanticBackend,
202	            match kept {
203	                0 => "1 component(s) resolved by the TypeScript checker".to_string(),
204	                kept => format!(
205	                    "1 component(s) resolved by the TypeScript checker; {kept} prop(s) it did not report keep their \
206	                     structural type"
207	                ),
208	            },
209	        );
210	        provenance.affects = vec![answer.key.clone()];
211	        answer.diagnostics.push(provenance);
212	        if unread > 0 {
213	            answer.diagnostics.push(unread_diagnostic(unread, vec![answer.key.clone()]));
214	        }
215	    }
216	}
217	
218	/// Keeps `answered` for `key` unless the cache was invalidated since the question was asked.
219	fn store(answers: &Answers, key: (String, u64), generation: u64, answered: Answered) {
220	    let mut cache = answers.lock().unwrap_or_else(PoisonError::into_inner);
221	    if cache.generation == generation {
222	        cache.answers.insert(key, answered);
223	    }
224	}
225	
226	/// The component a request asked about, as a late answer's thread, which has no [`ComponentAnswer`], knows it.
227	struct Asked {
228	    key: String,
229	    file_path: camino::Utf8PathBuf,
230	    display_name: String,
231	}
232	
233	impl From<&ComponentAnswer> for Asked {
234	    fn from(answer: &ComponentAnswer) -> Self {
235	        Self {
236	            key: answer.key.clone(),
237	            file_path: answer.entry.file_path.clone(),
238	            display_name: answer.entry.display_name.clone(),
239	        }
240	    }
241	}
242	
243	/// An outcome read for the component asked about.
244	struct Read {
245	    /// What is kept for the next request: the component and what the checker said about the request, each diagnostic
246	    /// naming the component.
247	    answered: Answered,
248	    /// What an unavailable checker says, which a session says once and not per component, so it is not kept.
249	    once: Vec<Diagnostic>,
250	}
251	
252	/// The component the checker answered for, and the diagnostics the request produced: a warning that came with an
253	/// answer (an edit the checker was not told about) is about this request, and a fallback's reason says why the
254	/// component kept its structural result.
255	fn read_outcome(asked: &Asked, outcome: SemanticOutcome) -> Read {
256	    let SemanticOutcome { components, fallbacks, diagnostics: reported } = outcome;
257	    // Only an outcome with no answer at all says the checker is unavailable.
258	    let unavailable = components.is_empty() && fallbacks.is_empty();
259	    let mut read = Read { answered: Answered::default(), once: Vec::new() };
260	    for mut diagnostic in reported {
261	        diagnostic.affects = vec![asked.key.clone()];
262	        if unavailable && diagnostic.severity == DiagnosticSeverity::Warning {
263	            read.once.push(diagnostic);
264	        } else {
265	            read.answered.diagnostics.push(diagnostic);
266	        }
267	    }
268	    for fallback in fallbacks {
269	        let mut info = Diagnostic::new(
270	            DiagnosticSeverity::Info,
271	            DiagnosticCode::SemanticBackend,
272	            format!("1 component(s) kept their structural result: {}", fallback.reason),
273	        );
274	        info.affects = vec![asked.key.clone()];
275	        read.answered.diagnostics.push(info);
276	    }
277	    read.answered.component = components
278	        .into_iter()
279	        .find(|found| found.file_path == asked.file_path && found.display_name == asked.display_name)
280	        .map(Arc::new);
281	    read
282	}
